using System.Collections.Concurrent;
using System.Text.Json;
using System.Threading.Channels;
using AirFlash.Core;
using Xunit;
namespace AirFlash.Tests;

// Each handshake or query phase preserves terminal process rejection. Each reply
// is generated by its command's SendAsync; nothing is queued across IPC phases.
public sealed class IpcConsumerPhaseTests
{
    private static readonly TimeSpan Limit = TimeSpan.FromSeconds(4);
    private static readonly SessionTiming Timing = new(Limit, Limit, Limit, TimeSpan.Zero);
    private const string ReceiverId = "synthetic-phase-receiver";
    private const string Message = "synthetic command rejection";
    private const string Rejection = "{\"version\":1,\"id\":\"\",\"session_id\":\"\",\"event\":\"error\",\"code\":\"command_error\",\"channel\":\"ipc\",\"host\":null,\"retryable\":false,\"message\":\"synthetic command rejection\"}";
    private static Receiver Receiver() => new(ReceiverId, "Synthetic phase receiver", "192.0.2.10", 7000);
    private static TaskCompletionSource Signal() => new(TaskCreationOptions.RunContinuationsAsynchronously);

    [Theory]
    [InlineData("playback_hello", false)]
    [InlineData("playback_hello", true)]
    [InlineData("pair_hello", false)]
    [InlineData("pair_hello", true)]
    [InlineData("playback_capabilities", false)]
    [InlineData("playback_capabilities", true)]
    public async Task OwnedAttemptPreservesProcessRejectionBeforePlaybackOrPair(string phase, bool originalMute)
    {
        var connection = new PhaseConnection(phase == "playback_capabilities" ? ReplyPhase.RejectCapabilities : ReplyPhase.RejectHello);
        var factory = new Factory(connection);
        var audio = new Audio(originalMute);
        var controller = new SessionController(factory, audio, timing: Timing);
        var failed = new TaskCompletionSource<SessionSnapshot>(TaskCreationOptions.RunContinuationsAsynchronously);
        var pinCalls = 0;
        controller.Changed += snapshot =>
        {
            if (snapshot.State != PlaybackState.Error) return;
            audio.ObserveFault();
            failed.TrySetResult(snapshot);
        };
        try
        {
            var settings = new AppSettings { ForceReconnect = true, MaxReconnectAttempts = 1, MuteWhileStreaming = true };
            if (phase == "pair_hello")
                await controller.PairAsync(Receiver(), settings, (_, cancellation) =>
                {
                    cancellation.ThrowIfCancellationRequested();
                    Interlocked.Increment(ref pinCalls);
                    return Task.FromResult<string?>("1234");
                }).WaitAsync(Limit);
            else await controller.StartAsync(Receiver(), settings).WaitAsync(Limit);

            await connection.HelloSent.Task.WaitAsync(Limit);
            if (phase == "playback_capabilities") await connection.CapabilitiesSent.Task.WaitAsync(Limit);
            var snapshot = await failed.Task.WaitAsync(Limit);
            AssertNotice(Assert.IsType<EngineNotice>(snapshot.Diagnostics?.LastFault));
            Assert.Equal(snapshot.Diagnostics!.LastFault!.Detail, snapshot.Message);
            Assert.Equal(0, snapshot.Diagnostics.ReconnectCount);

            // After the Error publication, the worker's outer finally performs
            // its last restoration. Join it through Stop only after observing
            // that cleanup, so Stop cannot manufacture a no-retry premise.
            await connection.DisposalCompleted.Task.WaitAsync(Limit);
            await audio.RestorationAfterFault.Task.WaitAsync(Limit);
            await controller.StopAsync().WaitAsync(Limit);
            Assert.Equal(1, factory.OpenCount);
            Assert.Equal(0, pinCalls);
            Assert.Equal(0, audio.MuteCalls);
            Assert.Equal(originalMute, audio.Muted);
            Assert.Equal(PlaybackState.Idle, controller.Snapshot.State);
            Assert.Contains("stop", connection.Commands);
            Assert.DoesNotContain("start", connection.Commands);
            Assert.DoesNotContain("pair", connection.Commands);
            Assert.DoesNotContain("pair_pin", connection.Commands);
            Assert.Equal(phase == "playback_capabilities" ? 1 : 0,
                connection.Commands.Count(command => command == "get_receiver_capabilities"));
        }
        finally { await controller.DisposeAsync().AsTask().WaitAsync(Limit); }
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public async Task CapabilityCatalogPreservesProcessRejectionAtHelloAndQueryReply(bool atHello)
    {
        var connection = new PhaseConnection(atHello ? ReplyPhase.RejectHello : ReplyPhase.RejectCapabilities);
        var factory = new Factory(connection);
        var catalog = new ReceiverCapabilityCatalog(factory);
        try
        {
            var error = await Assert.ThrowsAsync<EngineFailure>(() => catalog.QueryAsync(Receiver())).WaitAsync(Limit);
            AssertNotice(error.Notice);
            Assert.Equal(error.Notice.Detail, error.Message);
            Assert.True(connection.DisposalCompleted.Task.IsCompleted);
            Assert.Equal(1, factory.OpenCount);
            Assert.Equal(atHello ? new[] { "hello" } : new[] { "hello", "get_receiver_capabilities" }, connection.Commands);
        }
        finally { await connection.DisposeAsync(); }
    }

    [Fact]
    public async Task StartupHelloPreservesTheSameProcessRejection()
    {
        var connection = new PhaseConnection(ReplyPhase.RejectHello);
        var factory = new Factory(connection);
        var error = await Assert.ThrowsAsync<EngineFailure>(() => EngineHandshake.HelloAsync(factory, limit: Limit)).WaitAsync(Limit);
        AssertNotice(error.Notice);
        Assert.Equal(error.Notice.Detail, error.Message);
        Assert.True(connection.DisposalCompleted.Task.IsCompleted);
        Assert.Equal(1, factory.OpenCount);
        Assert.Equal(new[] { "hello" }, connection.Commands);
    }

    [Fact]
    public async Task ValidHelloWithoutSelectableCapabilitySupportRemainsUnknown()
    {
        var connection = new PhaseConnection(ReplyPhase.HealthyLegacy);
        var factory = new Factory(connection);
        var result = await new ReceiverCapabilityCatalog(factory).QueryAsync(Receiver()).WaitAsync(Limit);
        Assert.False(result.Known);
        Assert.Empty(result.Members);
        Assert.Empty(result.Select(new ReceiverOptions()));
        Assert.Equal(new[] { "hello" }, connection.Commands);
        Assert.True(connection.DisposalCompleted.Task.IsCompleted);
        Assert.Equal(1, factory.OpenCount);
    }

    [Fact]
    public async Task ValidCapabilityReplyRetainsItsSelectableProfile()
    {
        var connection = new PhaseConnection(ReplyPhase.HealthyCapabilities);
        var factory = new Factory(connection);
        var result = await new ReceiverCapabilityCatalog(factory).QueryAsync(Receiver()).WaitAsync(Limit);
        Assert.True(result.Known);
        var selected = Assert.Single(result.Select(new ReceiverOptions()));
        Assert.Equal(ReceiverId, selected.ReceiverId);
        Assert.Equal(44100, selected.Profile.SampleRate);
        Assert.Equal("alac", selected.Profile.SelectedCodec);
        Assert.Equal(new[] { "hello", "get_receiver_capabilities" }, connection.Commands);
        Assert.True(connection.DisposalCompleted.Task.IsCompleted);
        Assert.Equal(1, factory.OpenCount);
    }

    private static void AssertNotice(EngineNotice notice)
    {
        Assert.Equal("command_error", notice.Code);
        Assert.Equal("ipc", notice.Channel);
        Assert.Equal("", notice.Host);
        Assert.Equal(Message, notice.Message);
        Assert.Equal(false, notice.Retryable);
    }

    private enum ReplyPhase { RejectHello, RejectCapabilities, HealthyLegacy, HealthyCapabilities }

    private sealed class Factory(PhaseConnection connection) : IEngineFactory
    {
        private int _openCount;
        public int OpenCount => Volatile.Read(ref _openCount);
        public IEngineConnection Open()
        {
            if (Interlocked.Increment(ref _openCount) != 1) throw new IOException("Unexpected engine retry in phase verification.");
            return connection;
        }
    }

    private sealed class PhaseConnection(ReplyPhase phase) : IEngineConnection
    {
        private readonly Channel<string> _events = Channel.CreateUnbounded<string>();
        public readonly ConcurrentQueue<string> Commands = new();
        public readonly TaskCompletionSource HelloSent = Signal(), CapabilitiesSent = Signal(), DisposalCompleted = Signal();
        public Task SendAsync(string session, string command, object? parameters, CancellationToken cancellation)
        {
            cancellation.ThrowIfCancellationRequested();
            Commands.Enqueue(command);
            switch (command)
            {
                case "hello":
                    if (phase == ReplyPhase.RejectHello) _events.Writer.TryWrite(Rejection);
                    else
                    {
                        var capabilities = new List<string> { "receiver_profiles", "software_stereo", "continuity", "buffered_audio", "standby_release", "member_volume", "receiver_password", "application_capture" };
                        if (phase != ReplyPhase.HealthyLegacy) capabilities.Add("receiver_capabilities");
                        _events.Writer.TryWrite(JsonSerializer.Serialize(new { version = 1, session_id = session, @event = "hello", capabilities }));
                    }
                    HelloSent.TrySetResult();
                    break;
                case "get_receiver_capabilities":
                    if (phase == ReplyPhase.RejectCapabilities) _events.Writer.TryWrite(Rejection);
                    else _events.Writer.TryWrite(JsonSerializer.Serialize(new
                    {
                        version = 1, session_id = session, @event = "receiver_capabilities",
                        members = new[] { new { receiver_id = ReceiverId, host = "192.0.2.10", port = 7000, known = true,
                            profiles = new[] { new { codec = "auto", transport = "auto", timing = "auto", sample_rate = 44100,
                                selected_codec = "alac", selected_transport = "realtime", selected_timing = "ptp" } } } }
                    }));
                    CapabilitiesSent.TrySetResult();
                    break;
                case "start":
                    _events.Writer.TryWrite(JsonSerializer.Serialize(new { version = 1, session_id = session, @event = "streaming" }));
                    break;
                case "stop":
                    _events.Writer.TryComplete();
                    break;
            }
            return Task.CompletedTask;
        }
        public async ValueTask<JsonElement?> ReadAsync(CancellationToken cancellation)
        {
            try
            {
                using var document = JsonDocument.Parse(await _events.Reader.ReadAsync(cancellation));
                return document.RootElement.Clone();
            }
            catch (ChannelClosedException) { return null; }
        }
        public ValueTask DisposeAsync()
        {
            _events.Writer.TryComplete();
            DisposalCompleted.TrySetResult();
            return ValueTask.CompletedTask;
        }
    }

    private sealed class Audio(bool originalMute) : IAudioService
    {
        private readonly bool _originalMute = originalMute;
        private int _muteCalls, _faultObserved;
        private bool _muted = originalMute;
        public int MuteCalls => Volatile.Read(ref _muteCalls);
        public bool Muted => Volatile.Read(ref _muted);
        public readonly TaskCompletionSource RestorationAfterFault = Signal();
        public event Action? EndpointsChanged { add { } remove { } }
        public Task<IReadOnlyList<AudioEndpoint>> GetEndpointsAsync() => Task.FromResult<IReadOnlyList<AudioEndpoint>>([]);
        public Task<string?> GetDefaultEndpointIdAsync() => Task.FromResult<string?>("synthetic-phase-endpoint");
        public void ObserveFault() => Interlocked.Exchange(ref _faultObserved, 1);
        public Task MuteAsync(string? endpointId)
        {
            Interlocked.Increment(ref _muteCalls);
            Volatile.Write(ref _muted, true);
            return Task.CompletedTask;
        }
        public Task RestoreAsync()
        {
            Volatile.Write(ref _muted, _originalMute);
            if (Volatile.Read(ref _faultObserved) != 0) RestorationAfterFault.TrySetResult();
            return Task.CompletedTask;
        }
    }
}
